<script setup>
import AppSelect from '../../shared/components/AppSelect.vue';
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {useRouteRefresh} from '../../shared/route-refresh.js';
import {useSalesRuntime} from './sales-runtime.js';
import {receiptBlocks} from './sales-model.js';
import ReceiptCard from './ReceiptCard.vue';
import CatalogModal from '../catalog/CatalogModal.vue';
import '../catalog/catalog.css';
import './sales.css';
const vm=useSalesRuntime(),company=ref(''),productId=ref(''),design=ref(null),preview=ref(false),imageFile=ref(null),imageHash=ref(''),imageBusy=ref(false),imageUrl=ref(''),removeImage=ref(false),saved=ref('');
const draft=reactive({header:'',footer:'',color:'',order:[],text:'',qrMode:'inherit',rechargeTemplate:''}),key=vm.key();let controller,revision=0,objectUrl='';
const admin=computed(()=>vm.identity.value?.account.type==='system'),mainId=computed(()=>admin.value?null:vm.identity.value?.account.type==='main_agent'?vm.ownId.value:null);
const companies=computed(()=>[...new Map(vm.state.options.products.map(product=>[product.provider_id,{id:product.provider_id,name:product.provider_name}])).values()]);
const products=computed(()=>vm.state.options.products.filter(product=>Number(product.provider_id)===Number(company.value))),product=computed(()=>products.value.find(product=>Number(product.id)===Number(productId.value)));
const editable=computed(()=>admin.value?vm.can('branding.receipt')&&vm.can('products.edit'):mainId.value&&vm.can('branding.edit'));
const qrLayout=computed(()=>({qr_enabled:draft.qrMode==='inherit'?Boolean(design.value?.qr_system_enabled):draft.qrMode==='show',recharge_template:draft.qrMode==='inherit'?design.value?.qr_system_template||'':draft.rechargeTemplate.trim()}));
const previewReceipt=computed(()=>({product_name:product.value?.name,extra_fields:product.value?.extra_fields,design:design.value?{...design.value,...qrLayout.value,...(admin.value?{header:draft.header,footer:draft.footer,color:draft.color,display_order:draft.order}:{agent_text:draft.text,agent_color:draft.color,agent_image:removeImage.value?null:imageUrl.value || design.value.agent_image})}:null}));
const dirty=computed(()=>JSON.stringify(draft)!==saved.value || imageFile.value || removeImage.value!==Boolean(design.value?.agent_image_removed));
function clearFile(){if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl='';imageFile.value=null;imageUrl.value='';imageHash.value='';}
async function loadLayout({preserve=false}={}){controller?.abort();controller=new AbortController();const expected=++revision;if(!preserve){design.value=null;clearFile();}vm.state.error='';if(!product.value)return;try{const response=await vm.api.layout(product.value.id,{},controller.signal);if(expected!==revision||preserve&&dirty.value)return;if(preserve)clearFile();design.value=response.data;Object.assign(draft,{header:design.value.header,footer:design.value.footer,color:admin.value?design.value.color:design.value.agent_color,order:[...design.value.display_order],text:design.value.agent_text,qrMode:admin.value?(design.value.qr_system_enabled?'show':'hide'):design.value.qr_override?(design.value.qr_enabled?'show':'hide'):'inherit',rechargeTemplate:(admin.value?design.value.qr_system_template:design.value.recharge_template)||''});removeImage.value=Boolean(design.value.agent_image_removed);saved.value=JSON.stringify(draft);}catch(error){if(error.name!=='AbortError'&&expected===revision)vm.state.error=await vm.failure(error);}}
async function chooseImage(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;imageBusy.value=true;try{if(!['image/png','image/jpeg'].includes(file.type)||file.size>700000)throw Error('اختر صورة PNG أو JPEG بحجم لا يتجاوز 700000 بايت.');const bitmap=await createImageBitmap(file);const valid=bitmap.width<=4096&&bitmap.height<=4096;bitmap.close();if(!valid)throw Error('أبعاد الصورة يجب ألا تتجاوز 4096 بكسل.');const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());clearFile();imageHash.value=Array.from(new Uint8Array(digest),byte=>byte.toString(16).padStart(2,'0')).join('');imageFile.value=file;objectUrl=URL.createObjectURL(file);imageUrl.value=objectUrl;removeImage.value=false;}catch(error){vm.state.error=error.message;}finally{imageBusy.value=false;}}
function remove(){clearFile();removeImage.value=true;}
function move(index,direction){const next=index+direction;if(next<0||next>=draft.order.length)return;[draft.order[index],draft.order[next]]=[draft.order[next],draft.order[index]];}
async function save(){if(!editable.value||!design.value||imageBusy.value)return;const qr=draft.qrMode==='inherit'?{qr_enabled:null,recharge_template:null}:{qr_enabled:draft.qrMode==='show',recharge_template:draft.rechargeTemplate.trim()};const layout=admin.value?{header:draft.header,footer:draft.footer,color:draft.color,display_order:[...draft.order],...qr}:{agent_text:draft.text,agent_color:draft.color,agent_image_removed:removeImage.value,...qr};const payload={version:admin.value?design.value.version:design.value.personal_version,layout,...(!admin.value?{account_id:Number(mainId.value)}:{})};
  // Include the file identity in the client retry key; the server verifies the actual file hash.
  const identity={...payload,image_hash:imageHash.value || null};const result=await vm.execute(identity,key,(_value,signal)=>vm.api.saveLayout(product.value.id,{...payload,idempotency_key:_value.idempotency_key},signal,imageFile.value),'تم حفظ تصميم هذه الفئة.');if(result)await loadLayout();}
watch(company,()=>{productId.value=products.value[0]?.id || '';});watch(productId,loadLayout);
onMounted(async()=>{await vm.load(true);company.value=companies.value[0]?.id || '';});onBeforeUnmount(()=>{revision++;controller?.abort();clearFile();design.value=null;});
useRouteRefresh(async({signal})=>{try{vm.state.options=(await vm.session.api.request('/sales/configuration-options?compact=1',{signal,fresh:true})).data;await loadLayout({preserve:true});}catch(error){if(error.name!=='AbortError')vm.state.error=await vm.failure(error);}},{canRefresh:()=>!vm.state.busy&&!vm.state.loading&&!imageBusy.value&&!preview.value&&!!design.value&&!dirty.value});
</script>
<template><div class="catalog-workspace sales-workspace"><p v-if="vm.state.error" class="notice warn" role="alert">{{vm.state.error}}</p><p v-if="vm.state.notice" class="notice" role="status">{{vm.state.notice}}</p><section class="simple-card-workspace"><div class="card"><div class="simple-card-heading"><h3 v-if="!vm.pos.value">تصميم البطاقة</h3><div class="simple-card-selectors"><label>الشركة<AppSelect v-model="company" aria-label="شركة البطاقة"><option v-for="provider in companies" :key="provider.id" :value="provider.id">{{provider.name}}</option></AppSelect></label><label>الفئة<AppSelect v-model="productId" aria-label="فئة البطاقة"><option v-for="category in products" :key="category.id" :value="category.id">{{category.name}}</option></AppSelect></label></div></div></div><div v-if="product && design" class="two simple-card-designer"><form class="card simple-card-controls" @submit.prevent="save"><fieldset :disabled="!editable || vm.state.busy || imageBusy"><template v-if="admin"><label>النص العلوي<textarea v-model="draft.header" maxlength="1000" rows="2"></textarea></label><label>النص السفلي<textarea v-model="draft.footer" maxlength="1000" rows="2"></textarea></label><label class="personal-card-color">لون النص<input v-model="draft.color" type="color"></label><h3>ترتيب البطاقة</h3><div class="card-order-list"><div v-for="(block,index) in draft.order" :key="block" class="card-order-row"><span>{{receiptBlocks[block]}}</span><div class="actions"><button type="button" class="btn small" :disabled="index===0" :aria-label="`رفع ${receiptBlocks[block]}`" @click="move(index,-1)">↑</button><button type="button" class="btn small" :disabled="index===draft.order.length-1" :aria-label="`تنزيل ${receiptBlocks[block]}`" @click="move(index,1)">↓</button></div></div></div></template><template v-else><h3>صورتي على البطاقة</h3><div class="attachment-field"><label class="btn small">{{imageBusy?'جارٍ تجهيز الصورة':'إضافة صورة (اختياري)'}}<input type="file" accept="image/png,image/jpeg" hidden @change="chooseImage"></label><div v-if="!removeImage && (imageUrl || design.agent_image)" class="attachment-preview"><img :src="imageUrl || design.agent_image" alt="معاينة صورة الوكيل"><button type="button" class="btn small" @click="remove">إزالة</button></div></div><label>نصي على البطاقة<textarea v-model="draft.text" maxlength="1000" rows="3"></textarea></label><label class="personal-card-color">لون الخط<input v-model="draft.color" type="color"></label></template><section class="receipt-qr-controls"><h3>QR التعبئة</h3><label>ظهور QR في البطاقة<AppSelect v-model="draft.qrMode" aria-label="ظهور QR في البطاقة"><option v-if="!admin" value="inherit">حسب إعداد المدير</option><option value="show">إظهار QR التعبئة</option><option value="hide">إخفاء QR التعبئة</option></AppSelect></label><label v-if="draft.qrMode!=='inherit'">صيغة تعبئة هذه الفئة<input v-model="draft.rechargeTemplate" type="text" dir="ltr" maxlength="80" :required="draft.qrMode==='show'" placeholder="*123*{pin}#" autocomplete="off" spellcheck="false"><small v-if="!vm.pos.value">ضع {pin} مكان البن في كود التعبئة الصحيح للشركة. الرمز الظاهر مثال فقط.</small></label><p v-else class="muted">{{design.qr_system_enabled?'إظهار QR حسب إعداد المدير':'QR مخفي حسب إعداد المدير'}}</p><small v-if="!vm.pos.value">المسح يجهّز كود التعبئة في تطبيق الاتصال على الهواتف الداعمة؛ الزبون يضغط اتصال.</small></section></fieldset><div class="formfoot"><button type="button" class="btn" :disabled="imageBusy || !product" @click="preview=true">معاينة البطاقة</button><button class="btn primary" :disabled="!editable || vm.state.busy || imageBusy || !dirty">حفظ التعديلات</button></div></form><div class="card simple-card-preview"><h3>معاينة البطاقة</h3><ReceiptCard :receipt="previewReceipt" preview/></div></div><div v-else class="card empty">{{vm.state.loading?'جارٍ تحميل التصميم…':'لا توجد فئات متاحة'}}</div></section><CatalogModal v-if="preview && design" title="معاينة البطاقة" section="تصميم البطاقة" content-class="sales-modal" @close="preview=false"><ReceiptCard :receipt="previewReceipt" preview/></CatalogModal></div></template>
